@import "tw-animate-css";
@import "shadcn/tailwind.css";
@import "@fontsource-variable/space-grotesk";
@import "@fontsource-variable/jetbrains-mono";
@import "tailwindcss/preflight";

@custom-variant dark (&:is(.dark *));
@tailwind utilities;

/* ═══════════════════════════════════════════════════════════════════════
   LIGHT MODE (default)
   ═══════════════════════════════════════════════════════════════════════ */
:root {
  /* ── HardwareHub palette (light) ──────────────────────────────────── */
  --hw-page:          #f0f2f5;
  --hw-glow:          rgba(0, 130, 150, 0.06);
  --hw-card:          #ffffff;
  --hw-card-border:   rgba(0, 0, 0, 0.08);
  --hw-card-shadow:   0 4px 24px rgba(0, 0, 0, 0.08);
  --hw-icon-bg:       rgba(0, 130, 150, 0.08);
  --hw-icon-border:   rgba(0, 130, 150, 0.3);
  --hw-accent:        #008B8B;
  --hw-accent-fg:     #ffffff;
  --hw-title:         #111111;
  --hw-subtitle:      #666666;
  --hw-label:         #444444;
  --hw-input:         #f7f8fa;
  --hw-input-border:  rgba(0, 0, 0, 0.12);
  --hw-input-text:    #111111;
  --hw-placeholder:   #aaaaaa;
  --hw-divider:       rgba(0, 0, 0, 0.06);
  --hw-muted:         #666666;
  --hw-muted-border:  rgba(0, 0, 0, 0.12);
  --hw-error:         #dc2626;
  --hw-error-bg:      rgba(220, 38, 38, 0.06);
  --hw-error-border:  rgba(220, 38, 38, 0.3);

  /* ── Chat bubble V2 palette (light) ────────────────────────────────── */
  --hw-bubble-own-from:           #d2eded;
  --hw-bubble-own-to:             #b8e0e0;
  --hw-bubble-own-border:         rgba(0, 139, 139, 0.30);
  --hw-bubble-own-text:           #1a3a3a;
  --hw-bubble-own-shadow:         0 2px 10px rgba(0, 139, 139, 0.10);
  --hw-bubble-own-shadow-hover:   0 4px 18px rgba(0, 139, 139, 0.18);
  --hw-bubble-other-from:         #f4f5f7;
  --hw-bubble-other-to:           #eaecef;
  --hw-bubble-other-border:       rgba(0, 0, 0, 0.10);
  --hw-bubble-other-text:         #2a2a2a;
  --hw-bubble-other-shadow:       0 2px 8px rgba(0, 0, 0, 0.06);
  --hw-bubble-other-shadow-hover: 0 4px 14px rgba(0, 0, 0, 0.10);
  --hw-bubble-dot-own:            rgba(0, 139, 139, 0.35);
  --hw-bubble-dot-other:          rgba(0, 0, 0, 0.10);
  --hw-bubble-scanline-color:     rgba(0, 139, 139, 0.012);
  --hw-bubble-avatar-ring-shadow: 0 0 6px rgba(0, 139, 139, 0.18);
  --hw-bubble-sender-color:       #000000;
  --hw-bubble-time-own:           #008B8B;
  --hw-bubble-time-other:         #888888;
  --hw-bubble-status-read:        #008B8B;

  /* ── Vite boilerplate vars ────────────────────────────────────────── */
  --text: #6b6375;
  --text-h: #08060d;
  --bg: #fff;
  --border: oklch(0.922 0 0);
  --code-bg: #f4f3ec;
  --accent: oklch(0.97 0 0);
  --accent-bg: rgba(170, 59, 255, 0.1);
  --accent-border: rgba(170, 59, 255, 0.5);
  --social-bg: rgba(244, 243, 236, 0.5);
  --shadow:
    rgba(0, 0, 0, 0.1) 0 10px 15px -3px, rgba(0, 0, 0, 0.05) 0 4px 6px -2px;
  --sans: 'JetBrains Mono Variable', 'JetBrains Mono', ui-monospace, monospace;
  --heading: 'Space Grotesk Variable', 'Space Grotesk', system-ui, sans-serif;
  --mono: 'JetBrains Mono Variable', 'JetBrains Mono', ui-monospace, monospace;

  font: 18px/145% var(--sans);
  letter-spacing: 0.18px;
  color-scheme: light dark;
  color: var(--text);
  background: var(--bg);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;

  @media (max-width: 1024px) {
    font-size: 16px;
  }

  /* ── shadcn light tokens ──────────────────────────────────────────── */
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);
  --chart-1: oklch(0.809 0.105 251.813);
  --chart-2: oklch(0.623 0.214 259.815);
  --chart-3: oklch(0.546 0.245 262.881);
  --chart-4: oklch(0.488 0.243 264.376);
  --chart-5: oklch(0.424 0.199 265.638);
  --radius: 0.625rem;
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.97 0 0);
  --sidebar-accent-foreground: oklch(0.205 0 0);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.708 0 0);
}

/* ═══════════════════════════════════════════════════════════════════════
   DARK MODE (.dark class on <html>)
   ═══════════════════════════════════════════════════════════════════════ */
.dark {
  /* ── HardwareHub palette (dark) ───────────────────────────────────── */
  --hw-page:          #000000;
  --hw-glow:          rgba(0, 255, 255, 0.07);
  --hw-card:          #111111;
  --hw-card-border:   rgba(85, 85, 85, 0.6);
  --hw-card-shadow:   0 0 40px rgba(0, 255, 255, 0.05);
  --hw-icon-bg:       rgba(0, 255, 255, 0.1);
  --hw-icon-border:   rgba(0, 255, 255, 0.3);
  --hw-accent:        #00FFFF;
  --hw-accent-fg:     #000000;
  --hw-title:         #FFFFFF;
  --hw-subtitle:      #888888;
  --hw-label:         #cccccc;
  --hw-input:         #0a0a0a;
  --hw-input-border:  rgba(85, 85, 85, 0.6);
  --hw-input-text:    #FFFFFF;
  --hw-placeholder:   #666666;
  --hw-divider:       rgba(85, 85, 85, 0.3);
  --hw-muted:         #999999;
  --hw-muted-border:  rgba(85, 85, 85, 0.6);
  --hw-error:         #f87171;
  --hw-error-bg:      rgba(239, 68, 68, 0.1);
  --hw-error-border:  rgba(239, 68, 68, 0.3);

  /* ── Chat bubble V2 palette (dark) ─────────────────────────────────── */
  --hw-bubble-own-from:           #0a2a3a;
  --hw-bubble-own-to:             #061a28;
  --hw-bubble-own-border:         rgba(0, 255, 255, 0.25);
  --hw-bubble-own-text:           #d0f0f0;
  --hw-bubble-own-shadow:         0 0 8px rgba(0, 255, 255, 0.10), 0 2px 8px rgba(0, 0, 0, 0.30);
  --hw-bubble-own-shadow-hover:   0 0 16px rgba(0, 255, 255, 0.22), 0 4px 20px rgba(0, 0, 0, 0.40);
  --hw-bubble-other-from:         #0a1820;
  --hw-bubble-other-to:           #061014;
  --hw-bubble-other-border:       rgba(0, 255, 255, 0.12);
  --hw-bubble-other-text:         #a8d0d8;
  --hw-bubble-other-shadow:       0 0 4px rgba(0, 255, 255, 0.06), 0 2px 8px rgba(0, 0, 0, 0.30);
  --hw-bubble-other-shadow-hover: 0 0 12px rgba(0, 255, 255, 0.12), 0 4px 16px rgba(0, 0, 0, 0.40);
  --hw-bubble-dot-own:            rgba(0, 255, 255, 0.50);
  --hw-bubble-dot-other:          rgba(0, 255, 255, 0.25);
  --hw-bubble-scanline-color:     rgba(0, 255, 255, 0.015);
  --hw-bubble-avatar-ring-shadow: 0 0 8px rgba(0, 255, 255, 0.22);
  --hw-bubble-sender-color:       #ffffff;
  --hw-bubble-time-own:           #00FFFF;
  --hw-bubble-time-other:         rgba(0, 255, 255, 0.50);
  --hw-bubble-status-read:        #00FFFF;

  /* ── shadcn dark tokens ───────────────────────────────────────────── */
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.205 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.205 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.922 0 0);
  --primary-foreground: oklch(0.205 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.556 0 0);
  --chart-1: oklch(0.809 0.105 251.813);
  --chart-2: oklch(0.623 0.214 259.815);
  --chart-3: oklch(0.546 0.245 262.881);
  --chart-4: oklch(0.488 0.243 264.376);
  --chart-5: oklch(0.424 0.199 265.638);
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.556 0 0);
}

/* ── OS dark override for boilerplate vars ──────────────────────────── */
@media (prefers-color-scheme: dark) {
  :root {
    --text: #9ca3af;
    --text-h: #f3f4f6;
    --bg: #16171d;
    --border: #2e303a;
    --code-bg: #1f2028;
    --accent: #c084fc;
    --accent-bg: rgba(192, 132, 252, 0.15);
    --accent-border: rgba(192, 132, 252, 0.5);
    --social-bg: rgba(47, 48, 58, 0.5);
    --shadow:
      rgba(0, 0, 0, 0.4) 0 10px 15px -3px, rgba(0, 0, 0, 0.25) 0 4px 6px -2px;
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   TAILWIND THEME — map CSS vars → Tailwind tokens
   ═══════════════════════════════════════════════════════════════════════ */
@theme inline {
  /* ── Breakpoints (Tailwind v4 defaults — necesarios para sm:, md:, lg:…) ── */
  --breakpoint-sm: 40rem;
  --breakpoint-md: 48rem;
  --breakpoint-lg: 64rem;
  --breakpoint-xl: 80rem;
  --breakpoint-2xl: 96rem;

  --font-sans: 'JetBrains Mono Variable', 'JetBrains Mono', ui-monospace, monospace;
  --font-heading: 'Space Grotesk Variable', 'Space Grotesk', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono Variable', 'JetBrains Mono', ui-monospace, monospace;

  /* ── HardwareHub tokens ───────────────────────────────────────────── */
  --color-hw-page:          var(--hw-page);
  --color-hw-glow:          var(--hw-glow);
  --color-hw-card:          var(--hw-card);
  --color-hw-card-border:   var(--hw-card-border);
  --color-hw-icon-bg:       var(--hw-icon-bg);
  --color-hw-icon-border:   var(--hw-icon-border);
  --color-hw-accent:        var(--hw-accent);
  --color-hw-accent-fg:     var(--hw-accent-fg);
  --color-hw-title:         var(--hw-title);
  --color-hw-subtitle:      var(--hw-subtitle);
  --color-hw-label:         var(--hw-label);
  --color-hw-input:         var(--hw-input);
  --color-hw-input-border:  var(--hw-input-border);
  --color-hw-input-text:    var(--hw-input-text);
  --color-hw-placeholder:   var(--hw-placeholder);
  --color-hw-divider:       var(--hw-divider);
  --color-hw-muted:         var(--hw-muted);
  --color-hw-muted-border:  var(--hw-muted-border);
  --color-hw-error:         var(--hw-error);
  --color-hw-error-bg:      var(--hw-error-bg);
  --color-hw-error-border:  var(--hw-error-border);

  /* ── shadcn tokens ────────────────────────────────────────────────── */
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --color-foreground: var(--foreground);
  --color-background: var(--background);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}

/* ═══════════════════════════════════════════════════════════════════════
   LAYOUT FIXES — sidebar + header
   ═══════════════════════════════════════════════════════════════════════ */

/*
 * El sidebar container usa position:fixed desde shadcn/ui.
 * Lo forzamos a empezar siempre debajo del header (68px).
 * Esta regla gana sobre cualquier clase de Tailwind.
 */
[data-slot="sidebar-container"] {
  top: 68px !important;
  height: calc(100svh - 68px) !important;
}

/* ═══════════════════════════════════════════════════════════════════════
   GLOBAL BASE STYLES
   ═══════════════════════════════════════════════════════════════════════ */
#root {
  min-height: 100svh;
}

body {
  margin: 0;
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
    font-family: var(--font-sans), sans-serif;
    line-height: 1.5;
    letter-spacing: normal;
  }
  html {
    @apply font-sans;
  }

  /* ── Typography resets (boilerplate, layered so utilities can override) */
  h1, h2, h3, h4, h5, h6 {
    font-family: var(--heading), sans-serif;
    font-weight: 500;
    color: var(--text-h);
  }
  h1 {
    font-size: 56px;
    letter-spacing: -1.68px;
    margin: 32px 0;
  }
  h2 {
    font-size: 24px;
    line-height: 118%;
    letter-spacing: -0.24px;
    margin: 0 0 8px;
  }
  p {
    margin: 0;
  }
  code, .counter {
    font-family: var(--mono), monospace;
    display: inline-flex;
    border-radius: 4px;
    color: var(--text-h);
  }
  code {
    font-size: 15px;
    line-height: 135%;
    padding: 4px 8px;
    background: var(--code-bg);
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   HEADER — Espaciado
   ═══════════════════════════════════════════════════════════════════════ */

[data-slot="app-header"] {
  padding-left: 48px !important;
  padding-right: 48px !important;
}

/* Grupo izquierdo: icono + texto "HardwareHub" */
[data-slot="app-header"] > div:first-child {
  gap: 10px !important;
}

/* Grupo derecho: avatar + theme toggle */
[data-slot="app-header"] > div:last-child {
  gap: 24px !important;
}

/* ═══════════════════════════════════════════════════════════════════════
   DROPDOWN MENU — Espaciado
   ═══════════════════════════════════════════════════════════════════════ */

[data-slot="dropdown-menu-content"] {
  padding: 8px !important;
}

[data-slot="dropdown-menu-label"] {
  padding: 8px 12px !important;
}

[data-slot="dropdown-menu-item"] {
  padding: 8px 12px !important;
  gap: 10px !important;
}

[data-slot="dropdown-menu-separator"] {
  margin-top: 6px !important;
  margin-bottom: 6px !important;
}

/* ═══════════════════════════════════════════════════════════════════════
   COMPONENT UTILITIES — reusable patterns (replaces inline styles)
   ═══════════════════════════════════════════════════════════════════════ */

/* ── Dashboard layout ─────────────────────────────────────────────────── */

.hw-dashboard-content {
  max-width: 1680px;
  margin: 0 auto;
  padding: 24px 28px 32px;
}

/* ── Header avatar ────────────────────────────────────────────────────── */

.hw-header-avatar {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  border-radius: 50%;
  overflow: hidden;
  cursor: pointer;
  border: 1px solid var(--hw-card-border);
  background: var(--muted);
  display: flex;
  align-items: center;
  justify-content: center;
  outline: none;
  padding: 0;
}

.hw-header-avatar img {
  display: block;
  width: 32px;
  height: 32px;
  object-fit: cover;
}

.hw-header-avatar-initials {
  font-size: 11px;
  color: var(--muted-foreground);
  line-height: 1;
}

/* ── Sidebar ──────────────────────────────────────────────────────────── */

.hw-sidebar-container {
  display: flex;
  flex-direction: column;
  padding: 24px 12px 16px;
  gap: 4px;
}

.hw-sidebar-section-title {
  margin: 0 0 1rem;
  padding: 0 1rem;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.1rem;
  text-transform: uppercase;
  opacity: 0.8;
}

.hw-sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.hw-sidebar-divider {
  margin: 16px 0;
  height: 1px;
}

.hw-sidebar-link {
  gap: 12px;
  padding: 12px 16px;
}

/* ── Chat sidebar spacing ───────────────────────────────────────────── */

.hw-chat-sidebar-header {
  padding-top: 0.75rem;
  padding-bottom: 0.75rem;
}

.hw-chat-sidebar-title {
  margin: 0 !important;
  padding-left: 0.625rem !important;
  font-size: 0.9375rem !important;
  font-weight: 700 !important;
  line-height: 1.2 !important;
  letter-spacing: normal !important;
  color: var(--hw-title) !important;
}

.hw-chat-sidebar-header-expanded {
  padding-left: 1.25rem;
  padding-right: 1.25rem;
  margin-bottom: 0.75rem !important;
}

.hw-chat-sidebar-header-collapsed {
  padding-left: 0.75rem;
  padding-right: 0.75rem;
}

.hw-chat-sidebar-actions {
  gap: 0.75rem !important;
}

.hw-chat-sidebar-search .hw-chat-sidebar-search-addon {
  padding-left: 0.875rem !important;
  padding-right: 0.375rem !important;
}

.hw-chat-sidebar-search .hw-chat-sidebar-search-input {
  padding-left: 0.375rem !important;
}

.hw-chat-sidebar-list {
  padding-top: 0.5rem;
  padding-bottom: 0.5rem;
}

.hw-chat-conversation-item {
  padding-top: 0.4rem;
  padding-bottom: 0.4rem;
  padding-left: 0.4rem;
  padding-right: 0.4rem;
}

.hw-chat-conversation-item-expanded {
  gap: 0.75rem;
}

.hw-chat-conversation-item-content {
  gap: 0.2rem;
}

/* ── Chat input composer spacing ─────────────────────────────────────── */

.hw-chat-input-shell {
  padding-left: 2rem;
  padding-right: 2rem;
  padding-top: 1rem;
  padding-bottom: 1rem;
}

.hw-chat-input-row {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 1rem;
}

.hw-chat-input-field {
  flex: 1 1 auto;
  height: 2.75rem;
  border-radius: 9999px;
  padding-left: 1.25rem;
  padding-right: 1rem;
}

.hw-chat-send-btn {
  flex-shrink: 0;
  margin-left: 0.25rem;
  margin-right: 0.5rem;
  width: 2.75rem;
  height: 2.75rem;
}

/* ── Chat bubble V2 ───────────────────────────────────────────────────── */

.hw-bubble {
  position: relative;
  max-width: 350px;
  padding: 13px 17px;
  font-size: 0.925rem;
  line-height: 1.62;
  font-weight: 400;
  letter-spacing: 0.02em;
  word-break: break-word;
  cursor: default;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.hw-bubble-own {
  background: linear-gradient(135deg, var(--hw-bubble-own-from), var(--hw-bubble-own-to));
  border: 1px solid var(--hw-bubble-own-border);
  color: var(--hw-bubble-own-text);
  border-radius: 18px 4px 18px 18px;
  box-shadow: var(--hw-bubble-own-shadow);
}

.hw-bubble-other {
  background: linear-gradient(135deg, var(--hw-bubble-other-from), var(--hw-bubble-other-to));
  border: 1px solid var(--hw-bubble-other-border);
  color: var(--hw-bubble-other-text);
  border-radius: 4px 18px 18px 18px;
  box-shadow: var(--hw-bubble-other-shadow);
}

.hw-bubble-own.hw-bubble-hovered {
  transform: translateY(-1px);
  box-shadow: var(--hw-bubble-own-shadow-hover);
}

.hw-bubble-other.hw-bubble-hovered {
  transform: translateY(-1px);
  box-shadow: var(--hw-bubble-other-shadow-hover);
}

/* Scanline overlay */
.hw-bubble-scanline {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background-image:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 3px,
      var(--hw-bubble-scanline-color) 3px,
      var(--hw-bubble-scanline-color) 4px
    );
  pointer-events: none;
}

/* Decorative corner dots */
.hw-bubble-dot {
  position: absolute;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  pointer-events: none;
}

.hw-bubble-dot-tl {
  top: 6px;
  left: 6px;
}

.hw-bubble-dot-br {
  bottom: 6px;
  right: 6px;
  opacity: 0.4;
}

.hw-bubble-own .hw-bubble-dot {
  background: var(--hw-bubble-dot-own);
  box-shadow: 0 0 4px var(--hw-bubble-dot-own);
}

.hw-bubble-other .hw-bubble-dot {
  background: var(--hw-bubble-dot-other);
  box-shadow: 0 0 4px var(--hw-bubble-dot-other);
}

/* Bubble text (z-index above scanline) */
.hw-bubble-text {
  position: relative;
  z-index: 1;
  font-size: 0.925rem;
  line-height: 1.62;
  white-space: pre-wrap;
  overflow-wrap: break-word;
}

/* Chat message row + avatar spacing */
.hw-chat-message-row {
  display: flex;
  align-items: flex-start;
  gap: 0.25rem !important;
  margin-top: 1rem !important;
}

.hw-chat-message-row-own {
  flex-direction: row-reverse;
}

.hw-chat-message-row-other {
  flex-direction: row;
}

/* Avatar wrapper (positions the shadcn Avatar relative to the bubble) */
.hw-bubble-avatar-wrap {
  flex-shrink: 0;
  align-self: flex-start;
}

.hw-bubble-avatar-wrap-own {
  margin-top: -17.5px;
}

.hw-bubble-avatar-wrap-other {
  margin-top: 8px;
}

/* Cyan ring around the shadcn Avatar */
.hw-bubble-avatar-ring {
  border: 1.5px solid var(--hw-accent) !important;
  box-shadow: var(--hw-bubble-avatar-ring-shadow);
}

/* Fallback initials inside the Avatar */
.hw-bubble-avatar-fallback {
  font-size: 0.65rem !important;
  font-weight: 700 !important;
  letter-spacing: 0.06em;
  background: var(--hw-bubble-own-from) !important;
  color: var(--hw-accent) !important;
}

.hw-bubble-avatar-xl {
  width: 44px !important;
  height: 44px !important;
  min-width: 44px !important;
  min-height: 44px !important;
}

.hw-bubble-avatar-xl .hw-bubble-avatar-fallback {
  font-size: 0.72rem !important;
}

/* Sender name */
.hw-bubble-sender-name {
  font-size: 0.675rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: var(--hw-bubble-sender-color);
  margin-bottom: 4px;
  text-transform: uppercase;
}

/* Time + status row */
.hw-bubble-meta {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 4px;
  font-size: 0.625rem;
  letter-spacing: 0.08em;
  font-weight: 500;
  opacity: 0.55;
}

.hw-bubble-meta-own {
  color: var(--hw-bubble-time-own);
}

.hw-bubble-meta-other {
  color: var(--hw-bubble-time-other);
}

/* Status icon */
.hw-bubble-status {
  display: flex;
  align-items: center;
  color: currentColor;
}

.hw-bubble-status-read {
  color: var(--hw-bubble-status-read);
}

/* ── Chat layout helpers (kept from V1) ───────────────────────────────── */

.hw-chat-avatar-spacing {
  margin-right: 10px;
  margin-left: 6px;
}

.hw-chat-msg-spacer {
  height: 12px;
  width: 100%;
  display: block;
  pointer-events: none;
}

/* ── Unread badge ─────────────────────────────────────────────────────── */

.hw-unread-badge {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  font-weight: 700;
  font-size: 0.65rem;
  line-height: 1;
}

.hw-unread-badge-collapsed {
  position: absolute;
  top: 6px;
  right: 6px;
  height: 18px;
  min-width: 18px;
  padding-left: 6px;
  padding-right: 6px;
  z-index: 2;
}

.hw-unread-badge-expanded {
  height: 20px;
  min-width: 20px;
  padding-left: 6px;
  padding-right: 6px;
  margin-right: 6px;
}

/* ── User search result button ────────────────────────────────────────── */

.hw-user-result-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 10px;
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  cursor: pointer;
}

.hw-user-result-btn-hover {
  transition: background-color 150ms ease;
}

.hw-user-result-btn-hover:hover {
  background-color: var(--hw-icon-bg);
}

.hw-user-result-btn:disabled {
  cursor: not-allowed;
}

/* ── Unstyled button (resets for avatar click-targets etc.) ────────────── */

.hw-btn-reset {
  background: none;
  border: none;
  padding: 0;
}

/* ── Page containers ──────────────────────────────────────────────────── */

.hw-page-section {
  padding-left: 8px;
  padding-right: 8px;
  padding-top: 4px;
  padding-bottom: 8px;
}

.hw-page-flow {
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: 24px 0;
}

.hw-feed-container {
  max-width: 680px;
  margin: 0 auto;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.hw-users-container {
  max-width: 680px;
  margin: 0 auto;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hw-search-bar {
  max-width: 690px;
  margin: 0 auto;
  width: 100%;
  display: flex;
  gap: 8px;
  flex-wrap: nowrap;
  align-items: center;
  overflow-x: auto;
}

/* ── Foro page top section ────────────────────────────────────────────── */

.hw-foro-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
}

.hw-foro-header-brand {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  min-width: 0;
  flex: 1;
}

.hw-foro-header-brand-icon {
  margin-top: 0.15rem;
  flex-shrink: 0;
}

.hw-foro-header-copy {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
}

.hw-foro-header-title {
  margin: 0;
  font-size: 1.4rem;
  line-height: 1.15;
  font-weight: 700;
}

.hw-foro-header-subtitle {
  margin: 0;
  font-size: 0.85rem;
  line-height: 1.4;
  color: var(--hw-subtitle);
}

.hw-foro-new-post-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.625rem;
  height: auto;
  padding: 0.65rem 1rem;
  white-space: nowrap;
}

.hw-foro-search-row {
  max-width: 720px;
  margin: 0 auto;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: nowrap;
  overflow-x: auto;
}

.hw-foro-search-input {
  flex: 1 1 32rem;
  min-width: 17rem;
  max-width: 100%;
  padding-left: 1rem;
  padding-right: 0.75rem;
}

.hw-foro-search-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  height: auto;
  padding: 0.55rem 0.8rem;
  white-space: nowrap;
}

.hw-foro-search-clear-btn {
  flex-shrink: 0;
}

/* ── Montajes page ───────────────────────────────────────────────────── */

.hw-create-montaje-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
}

.hw-create-montaje-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-width: 0;
  flex: 1;
}

.hw-create-montaje-icon {
  flex-shrink: 0;
}

.hw-create-montaje-copy {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
}

.hw-create-montaje-title {
  margin: 0;
  font-size: 1.4rem;
  line-height: 1.15;
  font-weight: 700;
}

.hw-create-montaje-subtitle {
  margin: 0;
  font-size: 0.85rem;
  line-height: 1.4;
}

.hw-create-montaje-back-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding-left: 1rem;
  padding-right: 1rem;
  white-space: nowrap;
}

.hw-selector-card {
  border: 0 !important;
}

.hw-selector-trigger {
  align-items: center !important;
}

.hw-selector-trigger-main {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  flex: 1;
  min-width: 0;
}

.hw-selector-content {
  padding-top: 0.25rem;
}

.hw-selector-selected {
  padding: 0.75rem 0.95rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
  gap: 0.75rem;
}

.hw-selector-selected-copy {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-width: 0;
}

.hw-selector-selected-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-width: 0;
}

.hw-selector-toolbar {
  display: flex;
  gap: 0.75rem;
  margin-bottom: 0.95rem;
  flex-wrap: wrap;
  align-items: center;
}

.hw-selector-search-wrap {
  flex: 1;
  min-width: 14rem;
  position: relative;
}

.hw-selector-search-input {
  padding-left: 2.25rem !important;
}

.hw-selector-filters {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  flex-wrap: wrap;
}

.hw-selector-filter-select {
  height: 2rem;
  border-radius: 0.6rem;
  border: 1px solid var(--hw-input-border);
  background: var(--hw-input);
  color: var(--hw-input-text);
  padding: 0 0.65rem;
  font-size: 0.82rem;
}

.hw-selector-filter-select:focus {
  outline: none;
  border-color: var(--hw-accent);
}

.hw-selector-filter-select option {
  background: var(--hw-card);
  color: var(--hw-input-text);
}

.hw-selector-results {
  max-height: 320px;
  overflow-y: auto;
  padding-right: 0.1rem;
}

.hw-selector-results [data-slot="table-container"] {
  overflow-x: hidden;
}

.hw-selector-table {
  table-layout: fixed;
}

.hw-selector-table [data-slot="table-head"]:first-child,
.hw-selector-table [data-slot="table-cell"]:first-child {
  padding-right: 1rem;
}

.hw-selector-table [data-slot="table-head"]:nth-child(2),
.hw-selector-table [data-slot="table-cell"]:nth-child(2) {
  padding-left: 0.9rem;
}

.hw-selector-table [data-slot="table-body"] [data-slot="table-cell"] {
  padding-top: 0.55rem;
  padding-bottom: 0.55rem;
}

.hw-selector-model-cell {
  white-space: normal !important;
  width: 100%;
}

.hw-selector-model-wrap {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-width: 0;
}

.hw-selector-model-text {
  display: inline-block;
  min-width: 0;
}

.hw-selector-model-text-wrap {
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.hw-montajes-action-btn {
  gap: 0.75rem !important;
  padding-left: 1rem !important;
  padding-right: 1rem !important;
}

/* ── Empty / error states ─────────────────────────────────────────────── */

.hw-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 48px 16px;
  text-align: center;
}

.hw-error-state {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 48px 16px;
}

/* ── Card layout helpers ──────────────────────────────────────────────── */

.hw-card-body {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.hw-card-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.hw-card-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-top: 4px;
}

.hw-card-img {
  width: 100%;
  max-height: 420px;
  object-fit: cover;
  border-radius: 12px;
}

/* ── Profile page ─────────────────────────────────────────────────────── */

.hw-profile-card {
  padding: 28px;
  display: flex;
  gap: 24px;
  align-items: flex-start;
  flex-wrap: wrap;
}

.hw-profile-info {
  flex: 1;
  min-width: 200px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hw-profile-stats {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.hw-profile-actions {
  margin-top: 4px;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.hw-stat-chip {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px 20px;
  border-radius: 14px;
  min-width: 90px;
}

.hw-profile-avatar {
  width: 96px;
  height: 96px;
  font-size: 2rem;
}

.hw-profile-avatar-fallback {
  font-size: 1.6rem;
}

/* ── Action buttons (follow, chat, etc.) ──────────────────────────────── */

.hw-action-btn {
  font-size: 0.8rem;
  padding: 8px 20px;
  border-radius: 10px;
}

.hw-action-btn-outline {
  border-color: var(--hw-card-border);
}

/* ── Comment button ───────────────────────────────────────────────────── */

.hw-comment-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.78rem;
  padding: 6px 12px;
  border-radius: 10px;
  border: 1px solid var(--hw-card-border);
}

/* ── Name link button (in cards) ──────────────────────────────────────── */

.hw-name-link {
  background: none;
  border: none;
  padding: 0;
  font-size: 0.88rem;
  font-weight: 600;
  display: block;
}

/* ── Dialog title with icon ───────────────────────────────────────────── */

.hw-dialog-title-icon {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
}

/* ── Search result list container ─────────────────────────────────────── */

.hw-search-results {
  min-height: 120px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

/* ── Skeleton loading containers ──────────────────────────────────────── */

.hw-skeleton-list-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 4px;
}

/* ── Comment components ───────────────────────────────────────────────── */

.hw-comment-row {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.hw-comment-row-sm {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}

.hw-comment-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
}

.hw-comment-meta {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.hw-comment-name {
  background: none;
  border: none;
  padding: 0;
  font-size: 0.8rem;
  font-weight: 600;
}

.hw-comment-name-sm {
  background: none;
  border: none;
  padding: 0;
  font-size: 0.76rem;
  font-weight: 600;
}

.hw-comment-text {
  font-size: 0.82rem;
  line-height: 1.5;
  word-break: break-word;
}

.hw-comment-text-sm {
  font-size: 0.78rem;
  line-height: 1.5;
  word-break: break-word;
}

.hw-reply-thread {
  margin-left: 44px;
  margin-top: 8px;
  padding-left: 12px;
  border-left: 2px solid var(--hw-divider);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.hw-reply-input-wrap {
  margin-left: 44px;
  margin-top: 8px;
}

.hw-reply-btn {
  margin-top: 2px;
  padding: 2px 6px;
  height: auto;
  gap: 4px;
}

/* ── Comment input (textarea area) ────────────────────────────────────── */

.hw-comment-input-wrap {
  display: flex;
  gap: 8px;
  align-items: flex-end;
}

.hw-comment-input-wrap--border {
  border-top: 1px solid var(--hw-divider);
  padding-top: 14px;
  margin-top: 4px;
}

.hw-comment-textarea {
  flex: 1;
  resize: none;
  background: var(--hw-input);
  border: 1px solid var(--hw-input-border);
  border-radius: 10px;
  padding: 8px 12px;
  font-size: 0.8rem;
  line-height: 1.5;
  font-family: inherit;
  outline: none;
}

.hw-comment-send-btn {
  width: 32px;
  height: 32px;
  border-radius: 50%;
}

/* ── NewsCard/Grid ────────────────────────────────────────────────────── */

.hw-news-grid {
  column-gap: 8px;
  row-gap: 8px;
}

.hw-news-grid-item {
  padding: 10px;
}

.hw-news-card {
  margin: 10px;
}

.hw-news-card-img-wrap {
  height: 220px;
}

.hw-news-card-body {
  padding: 20px 24px 24px;
  box-sizing: border-box;
}

/* ── Dialog content padding override ──────────────────────────────────── */

.hw-dialog-padded {
  padding: 1.25rem 1.5rem;
}

.hw-start-chat-dialog {
  gap: 1.25rem !important;
}

.hw-start-chat-dialog-header {
  gap: 0.75rem !important;
}

.hw-start-chat-dialog-input {
  margin-top: 0.25rem;
}

.hw-start-chat-dialog-results {
  gap: 0.75rem;
}

/* ── Formulario de nueva publicación ──────────────────────────────────── */

.hw-pub-dialog-header {
  padding-bottom: 1.25rem;
}

.hw-pub-dialog-form {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  padding-top: 0.25rem;
  padding-bottom: 0.5rem;
}

.hw-pub-dialog-textarea {
  background: var(--hw-input);
  border-color: var(--hw-input-border);
  color: var(--hw-input-text);
  padding-left: 1rem !important;
  padding-right: 1rem !important;
}

.hw-pub-dialog-submit {
  height: auto;
  padding: 0.625rem 1.25rem;
}

/* ── Profile page ─────────────────────────────────────────────────────── */

.hw-profile-field {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.hw-profile-field-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.hw-profile-field-value {
  font-size: 0.88rem;
  font-weight: 500;
}

/* ── Stat chip with icon (row layout, PerfilPage variant) ────────────── */

.hw-stat-chip-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 20px;
  border-radius: 14px;
  min-width: 160px;
}

.hw-stat-chip-row-inner {
  display: flex;
  flex-direction: column;
}

.hw-stat-chip-row-value {
  font-size: 1.1rem;
  font-weight: 700;
}

.hw-stat-chip-row-label {
  font-size: 0.72rem;
}

/* ── Info row (account details) ───────────────────────────────────────── */

.hw-info-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 18px;
  border-radius: 12px;
}

/* ── Card section containers ──────────────────────────────────────────── */

.hw-card-section {
  padding: 28px;
}

.hw-card-section-title {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
}

.hw-card-section-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 10px;
}

/* ── Profile name heading ─────────────────────────────────────────────── */

.hw-profile-name {
  font-size: 1.35rem;
  font-weight: 700;
  margin: 0;
  line-height: 1.3;
}

.hw-profile-email {
  font-size: 0.82rem;
  margin: 4px 0 0;
}

/* ── Profile edit form ────────────────────────────────────────────────── */

.hw-profile-form {
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.hw-profile-form-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

/* ── Profile info column (PerfilPage variant, wider min-width) ────────── */

.hw-profile-info-wide {
  flex: 1;
  min-width: 240px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* ── Compare page ─────────────────────────────────────────────────────── */

.hw-compare-page {
  padding: 16px 20px 32px;
}

.hw-compare-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-right: 8px;
}

.hw-compare-section-separator {
  width: 100%;
  height: 18px;
  background: transparent;
}

.hw-compare-card-separator {
  border-top: 0;
  margin-top: 8px;
  padding-top: 10px;
}

.hw-compare-cats {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.hw-compare-cat-btn {
  font-size: 0.82rem;
  border-radius: 10px;
  padding: 8px 16px;
  gap: 6px;
}

.hw-compare-selectors {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.hw-compare-selector {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.hw-compare-selector-title {
  font-size: 0.85rem;
  font-weight: 600;
  margin: 0;
}

.hw-compare-selector-list {
  max-height: 260px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.hw-compare-selector-input {
  padding-left: 1.25rem !important;
  text-indent: 0.1rem;
}

.hw-compare-selector-item-main {
  display: flex;
  align-items: flex-start;
  column-gap: 0.9rem;
  width: 100%;
  min-width: 0;
}

.hw-compare-selector-item-text {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  row-gap: 0.12rem;
  padding-left: 0.12rem;
  overflow: hidden;
}

.hw-compare-selector-model {
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hw-compare-selector-fab {
  font-size: 0.68rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  opacity: 0.85;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hw-compare-skeleton-col {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.hw-compare-empty-text {
  font-size: 0.9rem;
}

.hw-compare-table-header {
  display: grid;
  grid-template-columns: 180px 1fr 1fr;
  padding: 18px 24px;
  gap: 20px;
}

.hw-compare-table-header-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  min-width: 0;
}

.hw-compare-table-header-thumb {
  display: flex;
  align-items: center;
  justify-content: center;
}

.hw-compare-table-header-label {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.hw-compare-table-header-model {
  font-size: 0.9rem;
  font-weight: 700;
  margin: 0;
  text-align: center;
  line-height: 1.35;
}

.hw-compare-table-header-fab {
  font-size: 0.7rem;
  margin: 0;
  text-align: center;
  opacity: 0.9;
}

.hw-compare-table-row {
  display: grid;
  grid-template-columns: 180px 1fr 1fr;
  padding: 14px 24px;
  gap: 20px;
  align-items: center;
}

.hw-compare-table-row-label {
  font-size: 0.78rem;
  font-weight: 500;
}

.hw-compare-table-cell {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.hw-compare-table-cell-value {
  font-size: 0.85rem;
}

.hw-compare-visual {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.hw-compare-visual-title {
  font-size: 0.85rem;
  font-weight: 600;
  margin: 0;
}

.hw-compare-visual-row {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.hw-compare-visual-labels {
  display: flex;
  justify-content: space-between;
  font-size: 0.72rem;
}

.hw-compare-bar-wrap {
  display: flex;
  gap: 8px;
  align-items: center;
}

.hw-compare-bar-track {
  direction: rtl;
}

/* ── Aprender page ────────────────────────────────────────────────────── */

.hw-aprender-page {
  padding: 12px 8px 16px;
}

.hw-aprender-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-right: 8px;
}

.hw-aprender-separator {
  width: 100%;
  height: 22px;
  background: transparent;
  margin: 0;
}

.hw-aprender-intro {
  padding: 24px 28px;
}

.hw-aprender-sections {
  display: flex;
  flex-direction: column;
  gap: 14px !important;
}

.hw-aprender-section-card + .hw-aprender-section-card {
  margin-top: 2px;
}

.hw-aprender-footer {
  padding: 32px 24px;
}

.hw-aprender-section-trigger {
  padding-left: 28px;
  padding-right: 24px;
  gap: 16px;
}

.hw-aprender-section-icon-wrap {
  margin-left: 2px;
}

.hw-aprender-section-title {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 600;
}

.hw-aprender-section-content {
  padding: 14px 24px 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ── Ayuda page ───────────────────────────────────────────────────────── */

.hw-ayuda-page {
  padding: 12px 8px 16px;
}

.hw-ayuda-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-right: 8px;
}

.hw-ayuda-separator {
  width: 100%;
  height: 22px;
  background: transparent;
}

.hw-ayuda-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hw-ayuda-section-title {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
  padding-left: 4px;
}

.hw-ayuda-section-items {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.hw-ayuda-category-separator {
  width: 100%;
  height: 18px;
  background: transparent;
}

.hw-ayuda-item-trigger {
  gap: 12px;
  padding: 16px 20px;
}

.hw-ayuda-item-answer {
  font-size: 0.84rem;
  line-height: 1.65;
  margin: 0;
  padding: 0 20px 16px;
}

.hw-ayuda-footer {
  padding: 32px 24px;
}

.hw-ayuda-footer-title {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
}

.hw-ayuda-footer-text {
  font-size: 0.84rem;
  margin: 8px 0 0;
}

@import "tw-animate-css";
@import "shadcn/tailwind.css";
@import "@fontsource-variable/space-grotesk";
@import "@fontsource-variable/jetbrains-mono";
@import "tailwindcss/preflight";

@custom-variant dark (&:is(.dark *));
@tailwind utilities;

/* ═══════════════════════════════════════════════════════════════════════
   LIGHT MODE (default)
   ═══════════════════════════════════════════════════════════════════════ */
:root {
  /* ── HardwareHub palette (light) ──────────────────────────────────── */
  --hw-page:          #f0f2f5;
  --hw-glow:          rgba(0, 130, 150, 0.06);
  --hw-card:          #ffffff;
  --hw-card-border:   rgba(0, 0, 0, 0.08);
  --hw-card-shadow:   0 4px 24px rgba(0, 0, 0, 0.08);
  --hw-icon-bg:       rgba(0, 130, 150, 0.08);
  --hw-icon-border:   rgba(0, 130, 150, 0.3);
  --hw-accent:        #008B8B;
  --hw-accent-fg:     #ffffff;
  --hw-title:         #111111;
  --hw-subtitle:      #666666;
  --hw-label:         #444444;
  --hw-input:         #f7f8fa;
  --hw-input-border:  rgba(0, 0, 0, 0.12);
  --hw-input-text:    #111111;
  --hw-placeholder:   #aaaaaa;
  --hw-divider:       rgba(0, 0, 0, 0.06);
  --hw-muted:         #666666;
  --hw-muted-border:  rgba(0, 0, 0, 0.12);
  --hw-error:         #dc2626;
  --hw-error-bg:      rgba(220, 38, 38, 0.06);
  --hw-error-border:  rgba(220, 38, 38, 0.3);

  /* ── Chat bubble V2 palette (light) ────────────────────────────────── */
  --hw-bubble-own-from:           #d2eded;
  --hw-bubble-own-to:             #b8e0e0;
  --hw-bubble-own-border:         rgba(0, 139, 139, 0.30);
  --hw-bubble-own-text:           #1a3a3a;
  --hw-bubble-own-shadow:         0 2px 10px rgba(0, 139, 139, 0.10);
  --hw-bubble-own-shadow-hover:   0 4px 18px rgba(0, 139, 139, 0.18);
  --hw-bubble-other-from:         #f4f5f7;
  --hw-bubble-other-to:           #eaecef;
  --hw-bubble-other-border:       rgba(0, 0, 0, 0.10);
  --hw-bubble-other-text:         #2a2a2a;
  --hw-bubble-other-shadow:       0 2px 8px rgba(0, 0, 0, 0.06);
  --hw-bubble-other-shadow-hover: 0 4px 14px rgba(0, 0, 0, 0.10);
  --hw-bubble-dot-own:            rgba(0, 139, 139, 0.35);
  --hw-bubble-dot-other:          rgba(0, 0, 0, 0.10);
  --hw-bubble-scanline-color:     rgba(0, 139, 139, 0.012);
  --hw-bubble-avatar-ring-shadow: 0 0 6px rgba(0, 139, 139, 0.18);
  --hw-bubble-sender-color:       #000000;
  --hw-bubble-time-own:           #008B8B;
  --hw-bubble-time-other:         #888888;
  --hw-bubble-status-read:        #008B8B;

  /* ── Vite boilerplate vars ────────────────────────────────────────── */
  --text: #6b6375;
  --text-h: #08060d;
  --bg: #fff;
  --border: oklch(0.922 0 0);
  --code-bg: #f4f3ec;
  --accent: oklch(0.97 0 0);
  --accent-bg: rgba(170, 59, 255, 0.1);
  --accent-border: rgba(170, 59, 255, 0.5);
  --social-bg: rgba(244, 243, 236, 0.5);
  --shadow:
    rgba(0, 0, 0, 0.1) 0 10px 15px -3px, rgba(0, 0, 0, 0.05) 0 4px 6px -2px;
  --sans: 'JetBrains Mono Variable', 'JetBrains Mono', ui-monospace, monospace;
  --heading: 'Space Grotesk Variable', 'Space Grotesk', system-ui, sans-serif;
  --mono: 'JetBrains Mono Variable', 'JetBrains Mono', ui-monospace, monospace;

  font: 18px/145% var(--sans);
  letter-spacing: 0.18px;
  color-scheme: light dark;
  color: var(--text);
  background: var(--bg);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;

  @media (max-width: 1024px) {
    font-size: 16px;
  }

  /* ── shadcn light tokens ──────────────────────────────────────────── */
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);
  --chart-1: oklch(0.809 0.105 251.813);
  --chart-2: oklch(0.623 0.214 259.815);
  --chart-3: oklch(0.546 0.245 262.881);
  --chart-4: oklch(0.488 0.243 264.376);
  --chart-5: oklch(0.424 0.199 265.638);
  --radius: 0.625rem;
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.97 0 0);
  --sidebar-accent-foreground: oklch(0.205 0 0);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.708 0 0);
}

/* ═══════════════════════════════════════════════════════════════════════
   DARK MODE (.dark class on <html>)
   ═══════════════════════════════════════════════════════════════════════ */
.dark {
  /* ── HardwareHub palette (dark) ───────────────────────────────────── */
  --hw-page:          #000000;
  --hw-glow:          rgba(0, 255, 255, 0.07);
  --hw-card:          #111111;
  --hw-card-border:   rgba(85, 85, 85, 0.6);
  --hw-card-shadow:   0 0 40px rgba(0, 255, 255, 0.05);
  --hw-icon-bg:       rgba(0, 255, 255, 0.1);
  --hw-icon-border:   rgba(0, 255, 255, 0.3);
  --hw-accent:        #00FFFF;
  --hw-accent-fg:     #000000;
  --hw-title:         #FFFFFF;
  --hw-subtitle:      #888888;
  --hw-label:         #cccccc;
  --hw-input:         #0a0a0a;
  --hw-input-border:  rgba(85, 85, 85, 0.6);
  --hw-input-text:    #FFFFFF;
  --hw-placeholder:   #666666;
  --hw-divider:       rgba(85, 85, 85, 0.3);
  --hw-muted:         #999999;
  --hw-muted-border:  rgba(85, 85, 85, 0.6);
  --hw-error:         #f87171;
  --hw-error-bg:      rgba(239, 68, 68, 0.1);
  --hw-error-border:  rgba(239, 68, 68, 0.3);

  /* ── Chat bubble V2 palette (dark) ─────────────────────────────────── */
  --hw-bubble-own-from:           #0a2a3a;
  --hw-bubble-own-to:             #061a28;
  --hw-bubble-own-border:         rgba(0, 255, 255, 0.25);
  --hw-bubble-own-text:           #d0f0f0;
  --hw-bubble-own-shadow:         0 0 8px rgba(0, 255, 255, 0.10), 0 2px 8px rgba(0, 0, 0, 0.30);
  --hw-bubble-own-shadow-hover:   0 0 16px rgba(0, 255, 255, 0.22), 0 4px 20px rgba(0, 0, 0, 0.40);
  --hw-bubble-other-from:         #0a1820;
  --hw-bubble-other-to:           #061014;
  --hw-bubble-other-border:       rgba(0, 255, 255, 0.12);
  --hw-bubble-other-text:         #a8d0d8;
  --hw-bubble-other-shadow:       0 0 4px rgba(0, 255, 255, 0.06), 0 2px 8px rgba(0, 0, 0, 0.30);
  --hw-bubble-other-shadow-hover: 0 0 12px rgba(0, 255, 255, 0.12), 0 4px 16px rgba(0, 0, 0, 0.40);
  --hw-bubble-dot-own:            rgba(0, 255, 255, 0.50);
  --hw-bubble-dot-other:          rgba(0, 255, 255, 0.25);
  --hw-bubble-scanline-color:     rgba(0, 255, 255, 0.015);
  --hw-bubble-avatar-ring-shadow: 0 0 8px rgba(0, 255, 255, 0.22);
  --hw-bubble-sender-color:       #ffffff;
  --hw-bubble-time-own:           #00FFFF;
  --hw-bubble-time-other:         rgba(0, 255, 255, 0.50);
  --hw-bubble-status-read:        #00FFFF;

  /* ── shadcn dark tokens ───────────────────────────────────────────── */
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.205 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.205 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.922 0 0);
  --primary-foreground: oklch(0.205 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.556 0 0);
  --chart-1: oklch(0.809 0.105 251.813);
  --chart-2: oklch(0.623 0.214 259.815);
  --chart-3: oklch(0.546 0.245 262.881);
  --chart-4: oklch(0.488 0.243 264.376);
  --chart-5: oklch(0.424 0.199 265.638);
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.556 0 0);
}

/* ── OS dark override for boilerplate vars ──────────────────────────── */
@media (prefers-color-scheme: dark) {
  :root {
    --text: #9ca3af;
    --text-h: #f3f4f6;
    --bg: #16171d;
    --border: #2e303a;
    --code-bg: #1f2028;
    --accent: #c084fc;
    --accent-bg: rgba(192, 132, 252, 0.15);
    --accent-border: rgba(192, 132, 252, 0.5);
    --social-bg: rgba(47, 48, 58, 0.5);
    --shadow:
      rgba(0, 0, 0, 0.4) 0 10px 15px -3px, rgba(0, 0, 0, 0.25) 0 4px 6px -2px;
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   TAILWIND THEME — map CSS vars → Tailwind tokens
   ═══════════════════════════════════════════════════════════════════════ */
@theme inline {
  /* ── Breakpoints (Tailwind v4 defaults — necesarios para sm:, md:, lg:…) ── */
  --breakpoint-sm: 40rem;
  --breakpoint-md: 48rem;
  --breakpoint-lg: 64rem;
  --breakpoint-xl: 80rem;
  --breakpoint-2xl: 96rem;

  --font-sans: 'JetBrains Mono Variable', 'JetBrains Mono', ui-monospace, monospace;
  --font-heading: 'Space Grotesk Variable', 'Space Grotesk', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono Variable', 'JetBrains Mono', ui-monospace, monospace;

  /* ── HardwareHub tokens ───────────────────────────────────────────── */
  --color-hw-page:          var(--hw-page);
  --color-hw-glow:          var(--hw-glow);
  --color-hw-card:          var(--hw-card);
  --color-hw-card-border:   var(--hw-card-border);
  --color-hw-icon-bg:       var(--hw-icon-bg);
  --color-hw-icon-border:   var(--hw-icon-border);
  --color-hw-accent:        var(--hw-accent);
  --color-hw-accent-fg:     var(--hw-accent-fg);
  --color-hw-title:         var(--hw-title);
  --color-hw-subtitle:      var(--hw-subtitle);
  --color-hw-label:         var(--hw-label);
  --color-hw-input:         var(--hw-input);
  --color-hw-input-border:  var(--hw-input-border);
  --color-hw-input-text:    var(--hw-input-text);
  --color-hw-placeholder:   var(--hw-placeholder);
  --color-hw-divider:       var(--hw-divider);
  --color-hw-muted:         var(--hw-muted);
  --color-hw-muted-border:  var(--hw-muted-border);
  --color-hw-error:         var(--hw-error);
  --color-hw-error-bg:      var(--hw-error-bg);
  --color-hw-error-border:  var(--hw-error-border);

  /* ── shadcn tokens ────────────────────────────────────────────────── */
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --color-foreground: var(--foreground);
  --color-background: var(--background);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}

/* ═══════════════════════════════════════════════════════════════════════
   LAYOUT FIXES — sidebar + header
   ═══════════════════════════════════════════════════════════════════════ */

/*
 * El sidebar container usa position:fixed desde shadcn/ui.
 * Lo forzamos a empezar siempre debajo del header (68px).
 * Esta regla gana sobre cualquier clase de Tailwind.
 */
[data-slot="sidebar-container"] {
  top: 68px !important;
  height: calc(100svh - 68px) !important;
}

/* ═══════════════════════════════════════════════════════════════════════
   GLOBAL BASE STYLES
   ═══════════════════════════════════════════════════════════════════════ */
#root {
  min-height: 100svh;
}

body {
  margin: 0;
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
    font-family: var(--font-sans), sans-serif;
    line-height: 1.5;
    letter-spacing: normal;
  }
  html {
    @apply font-sans;
  }

  /* ── Typography resets (boilerplate, layered so utilities can override) */
  h1, h2, h3, h4, h5, h6 {
    font-family: var(--heading), sans-serif;
    font-weight: 500;
    color: var(--text-h);
  }
  h1 {
    font-size: 56px;
    letter-spacing: -1.68px;
    margin: 32px 0;
  }
  h2 {
    font-size: 24px;
    line-height: 118%;
    letter-spacing: -0.24px;
    margin: 0 0 8px;
  }
  p {
    margin: 0;
  }
  code, .counter {
    font-family: var(--mono), monospace;
    display: inline-flex;
    border-radius: 4px;
    color: var(--text-h);
  }
  code {
    font-size: 15px;
    line-height: 135%;
    padding: 4px 8px;
    background: var(--code-bg);
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   HEADER — Espaciado
   ═══════════════════════════════════════════════════════════════════════ */

[data-slot="app-header"] {
  padding-left: 48px !important;
  padding-right: 48px !important;
}

/* Grupo izquierdo: icono + texto "HardwareHub" */
[data-slot="app-header"] > div:first-child {
  gap: 10px !important;
}

/* Grupo derecho: avatar + theme toggle */
[data-slot="app-header"] > div:last-child {
  gap: 24px !important;
}

/* ═══════════════════════════════════════════════════════════════════════
   DROPDOWN MENU — Espaciado
   ═══════════════════════════════════════════════════════════════════════ */

[data-slot="dropdown-menu-content"] {
  padding: 8px !important;
}

[data-slot="dropdown-menu-label"] {
  padding: 8px 12px !important;
}

[data-slot="dropdown-menu-item"] {
  padding: 8px 12px !important;
  gap: 10px !important;
}

[data-slot="dropdown-menu-separator"] {
  margin-top: 6px !important;
  margin-bottom: 6px !important;
}

/* ═══════════════════════════════════════════════════════════════════════
   COMPONENT UTILITIES — reusable patterns (replaces inline styles)
   ═══════════════════════════════════════════════════════════════════════ */

/* ── Dashboard layout ─────────────────────────────────────────────────── */

.hw-dashboard-content {
  max-width: 1680px;
  margin: 0 auto;
  padding: 24px 28px 32px;
}

/* ── Header avatar ────────────────────────────────────────────────────── */

.hw-header-avatar {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  border-radius: 50%;
  overflow: hidden;
  cursor: pointer;
  border: 1px solid var(--hw-card-border);
  background: var(--muted);
  display: flex;
  align-items: center;
  justify-content: center;
  outline: none;
  padding: 0;
}

.hw-header-avatar img {
  display: block;
  width: 32px;
  height: 32px;
  object-fit: cover;
}

.hw-header-avatar-initials {
  font-size: 11px;
  color: var(--muted-foreground);
  line-height: 1;
}

/* ── Sidebar ──────────────────────────────────────────────────────────── */

.hw-sidebar-container {
  display: flex;
  flex-direction: column;
  padding: 24px 12px 16px;
  gap: 4px;
}

.hw-sidebar-section-title {
  margin: 0 0 1rem;
  padding: 0 1rem;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.1rem;
  text-transform: uppercase;
  opacity: 0.8;
}

.hw-sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.hw-sidebar-divider {
  margin: 16px 0;
  height: 1px;
}

.hw-sidebar-link {
  gap: 12px;
  padding: 12px 16px;
}

/* ── Chat sidebar spacing ───────────────────────────────────────────── */

.hw-chat-sidebar-header {
  padding-top: 0.75rem;
  padding-bottom: 0.75rem;
}

.hw-chat-sidebar-title {
  margin: 0 !important;
  padding-left: 0.625rem !important;
  font-size: 0.9375rem !important;
  font-weight: 700 !important;
  line-height: 1.2 !important;
  letter-spacing: normal !important;
  color: var(--hw-title) !important;
}

.hw-chat-sidebar-header-expanded {
  padding-left: 1.25rem;
  padding-right: 1.25rem;
  margin-bottom: 0.75rem !important;
}

.hw-chat-sidebar-header-collapsed {
  padding-left: 0.75rem;
  padding-right: 0.75rem;
}

.hw-chat-sidebar-actions {
  gap: 0.75rem !important;
}

.hw-chat-sidebar-search .hw-chat-sidebar-search-addon {
  padding-left: 0.875rem !important;
  padding-right: 0.375rem !important;
}

.hw-chat-sidebar-search .hw-chat-sidebar-search-input {
  padding-left: 0.375rem !important;
}

.hw-chat-sidebar-list {
  padding-top: 0.5rem;
  padding-bottom: 0.5rem;
}

.hw-chat-conversation-item {
  padding-top: 0.4rem;
  padding-bottom: 0.4rem;
  padding-left: 0.4rem;
  padding-right: 0.4rem;
}

.hw-chat-conversation-item-expanded {
  gap: 0.75rem;
}

.hw-chat-conversation-item-content {
  gap: 0.2rem;
}

/* ── Chat input composer spacing ─────────────────────────────────────── */

.hw-chat-input-shell {
  padding-left: 2rem;
  padding-right: 2rem;
  padding-top: 1rem;
  padding-bottom: 1rem;
}

.hw-chat-input-row {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 1rem;
}

.hw-chat-input-field {
  flex: 1 1 auto;
  height: 2.75rem;
  border-radius: 9999px;
  padding-left: 1.25rem;
  padding-right: 1rem;
}

.hw-chat-send-btn {
  flex-shrink: 0;
  margin-left: 0.25rem;
  margin-right: 0.5rem;
  width: 2.75rem;
  height: 2.75rem;
}

/* ── Chat bubble V2 ───────────────────────────────────────────────────── */

.hw-bubble {
  position: relative;
  max-width: 350px;
  padding: 13px 17px;
  font-size: 0.925rem;
  line-height: 1.62;
  font-weight: 400;
  letter-spacing: 0.02em;
  word-break: break-word;
  cursor: default;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.hw-bubble-own {
  background: linear-gradient(135deg, var(--hw-bubble-own-from), var(--hw-bubble-own-to));
  border: 1px solid var(--hw-bubble-own-border);
  color: var(--hw-bubble-own-text);
  border-radius: 18px 4px 18px 18px;
  box-shadow: var(--hw-bubble-own-shadow);
}

.hw-bubble-other {
  background: linear-gradient(135deg, var(--hw-bubble-other-from), var(--hw-bubble-other-to));
  border: 1px solid var(--hw-bubble-other-border);
  color: var(--hw-bubble-other-text);
  border-radius: 4px 18px 18px 18px;
  box-shadow: var(--hw-bubble-other-shadow);
}

.hw-bubble-own.hw-bubble-hovered {
  transform: translateY(-1px);
  box-shadow: var(--hw-bubble-own-shadow-hover);
}

.hw-bubble-other.hw-bubble-hovered {
  transform: translateY(-1px);
  box-shadow: var(--hw-bubble-other-shadow-hover);
}

/* Scanline overlay */
.hw-bubble-scanline {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background-image:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 3px,
      var(--hw-bubble-scanline-color) 3px,
      var(--hw-bubble-scanline-color) 4px
    );
  pointer-events: none;
}

/* Decorative corner dots */
.hw-bubble-dot {
  position: absolute;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  pointer-events: none;
}

.hw-bubble-dot-tl {
  top: 6px;
  left: 6px;
}

.hw-bubble-dot-br {
  bottom: 6px;
  right: 6px;
  opacity: 0.4;
}

.hw-bubble-own .hw-bubble-dot {
  background: var(--hw-bubble-dot-own);
  box-shadow: 0 0 4px var(--hw-bubble-dot-own);
}

.hw-bubble-other .hw-bubble-dot {
  background: var(--hw-bubble-dot-other);
  box-shadow: 0 0 4px var(--hw-bubble-dot-other);
}

/* Bubble text (z-index above scanline) */
.hw-bubble-text {
  position: relative;
  z-index: 1;
  font-size: 0.925rem;
  line-height: 1.62;
  white-space: pre-wrap;
  overflow-wrap: break-word;
}

/* Chat message row + avatar spacing */
.hw-chat-message-row {
  display: flex;
  align-items: flex-start;
  gap: 0.25rem !important;
  margin-top: 1rem !important;
}

.hw-chat-message-row-own {
  flex-direction: row-reverse;
}

.hw-chat-message-row-other {
  flex-direction: row;
}

/* Avatar wrapper (positions the shadcn Avatar relative to the bubble) */
.hw-bubble-avatar-wrap {
  flex-shrink: 0;
  align-self: flex-start;
}

.hw-bubble-avatar-wrap-own {
  margin-top: -17.5px;
}

.hw-bubble-avatar-wrap-other {
  margin-top: 8px;
}

/* Cyan ring around the shadcn Avatar */
.hw-bubble-avatar-ring {
  border: 1.5px solid var(--hw-accent) !important;
  box-shadow: var(--hw-bubble-avatar-ring-shadow);
}

/* Fallback initials inside the Avatar */
.hw-bubble-avatar-fallback {
  font-size: 0.65rem !important;
  font-weight: 700 !important;
  letter-spacing: 0.06em;
  background: var(--hw-bubble-own-from) !important;
  color: var(--hw-accent) !important;
}

.hw-bubble-avatar-xl {
  width: 44px !important;
  height: 44px !important;
  min-width: 44px !important;
  min-height: 44px !important;
}

.hw-bubble-avatar-xl .hw-bubble-avatar-fallback {
  font-size: 0.72rem !important;
}

/* Sender name */
.hw-bubble-sender-name {
  font-size: 0.675rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: var(--hw-bubble-sender-color);
  margin-bottom: 4px;
  text-transform: uppercase;
}

/* Time + status row */
.hw-bubble-meta {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 4px;
  font-size: 0.625rem;
  letter-spacing: 0.08em;
  font-weight: 500;
  opacity: 0.55;
}

.hw-bubble-meta-own {
  color: var(--hw-bubble-time-own);
}

.hw-bubble-meta-other {
  color: var(--hw-bubble-time-other);
}

/* Status icon */
.hw-bubble-status {
  display: flex;
  align-items: center;
  color: currentColor;
}

.hw-bubble-status-read {
  color: var(--hw-bubble-status-read);
}

/* ── Chat layout helpers (kept from V1) ───────────────────────────────── */

.hw-chat-avatar-spacing {
  margin-right: 10px;
  margin-left: 6px;
}

.hw-chat-msg-spacer {
  height: 12px;
  width: 100%;
  display: block;
  pointer-events: none;
}

/* ── Unread badge ─────────────────────────────────────────────────────── */

.hw-unread-badge {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  font-weight: 700;
  font-size: 0.65rem;
  line-height: 1;
}

.hw-unread-badge-collapsed {
  position: absolute;
  top: 6px;
  right: 6px;
  height: 18px;
  min-width: 18px;
  padding-left: 6px;
  padding-right: 6px;
  z-index: 2;
}

.hw-unread-badge-expanded {
  height: 20px;
  min-width: 20px;
  padding-left: 6px;
  padding-right: 6px;
  margin-right: 6px;
}

/* ── User search result button ────────────────────────────────────────── */

.hw-user-result-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 10px;
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  cursor: pointer;
}

.hw-user-result-btn-hover {
  transition: background-color 150ms ease;
}

.hw-user-result-btn-hover:hover {
  background-color: var(--hw-icon-bg);
}

.hw-user-result-btn:disabled {
  cursor: not-allowed;
}

/* ── Unstyled button (resets for avatar click-targets etc.) ────────────── */

.hw-btn-reset {
  background: none;
  border: none;
  padding: 0;
}

/* ── Page containers ──────────────────────────────────────────────────── */

.hw-page-section {
  padding-left: 8px;
  padding-right: 8px;
  padding-top: 4px;
  padding-bottom: 8px;
}

.hw-page-flow {
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: 24px 0;
}

.hw-feed-container {
  max-width: 680px;
  margin: 0 auto;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.hw-users-container {
  max-width: 680px;
  margin: 0 auto;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hw-search-bar {
  max-width: 690px;
  margin: 0 auto;
  width: 100%;
  display: flex;
  gap: 8px;
  flex-wrap: nowrap;
  align-items: center;
  overflow-x: auto;
}

/* ── Foro page top section ────────────────────────────────────────────── */

.hw-foro-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
}

.hw-foro-header-brand {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  min-width: 0;
  flex: 1;
}

.hw-foro-header-brand-icon {
  margin-top: 0.15rem;
  flex-shrink: 0;
}

.hw-foro-header-copy {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
}

.hw-foro-header-title {
  margin: 0;
  font-size: 1.4rem;
  line-height: 1.15;
  font-weight: 700;
}

.hw-foro-header-subtitle {
  margin: 0;
  font-size: 0.85rem;
  line-height: 1.4;
  color: var(--hw-subtitle);
}

.hw-foro-new-post-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.625rem;
  height: auto;
  padding: 0.65rem 1rem;
  white-space: nowrap;
}

.hw-foro-search-row {
  max-width: 720px;
  margin: 0 auto;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: nowrap;
  overflow-x: auto;
}

.hw-foro-search-input {
  flex: 1 1 32rem;
  min-width: 17rem;
  max-width: 100%;
  padding-left: 1rem;
  padding-right: 0.75rem;
}

.hw-foro-search-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  height: auto;
  padding: 0.55rem 0.8rem;
  white-space: nowrap;
}

.hw-foro-search-clear-btn {
  flex-shrink: 0;
}

/* ── Montajes page ───────────────────────────────────────────────────── */

.hw-create-montaje-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
}

.hw-create-montaje-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-width: 0;
  flex: 1;
}

.hw-create-montaje-icon {
  flex-shrink: 0;
}

.hw-create-montaje-copy {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
}

.hw-create-montaje-title {
  margin: 0;
  font-size: 1.4rem;
  line-height: 1.15;
  font-weight: 700;
}

.hw-create-montaje-subtitle {
  margin: 0;
  font-size: 0.85rem;
  line-height: 1.4;
}

.hw-create-montaje-back-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding-left: 1rem;
  padding-right: 1rem;
  white-space: nowrap;
}

.hw-selector-card {
  border: 0 !important;
}

.hw-selector-trigger {
  align-items: center !important;
}

.hw-selector-trigger-main {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  flex: 1;
  min-width: 0;
}

.hw-selector-type-icon {
  margin-left: 0.25rem;
}

.hw-selector-content {
  padding-top: 0.25rem;
}

.hw-selector-selected {
  padding: 0.75rem 0.95rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
  gap: 0.75rem;
}

.hw-selector-selected-copy {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-width: 0;
}

.hw-selector-selected-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-width: 0;
}

.hw-selector-toolbar {
  display: flex;
  gap: 0.75rem;
  margin-bottom: 0.95rem;
  flex-wrap: wrap;
  align-items: center;
}

.hw-selector-search-wrap {
  flex: 1;
  min-width: 14rem;
  position: relative;
}

.hw-selector-search-input {
  padding-left: 2.25rem !important;
}

.hw-selector-filters {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  flex-wrap: wrap;
}

.hw-selector-filter-select {
  height: 2rem;
  border-radius: 0.6rem;
  border: 1px solid var(--hw-input-border);
  background: var(--hw-input);
  color: var(--hw-input-text);
  padding: 0 0.65rem;
  font-size: 0.82rem;
}

.hw-selector-filter-select:focus {
  outline: none;
  border-color: var(--hw-accent);
}

.hw-selector-filter-select option {
  background: var(--hw-card);
  color: var(--hw-input-text);
}

.hw-selector-results {
  max-height: 320px;
  overflow-y: auto;
  padding-right: 0.1rem;
}

.hw-selector-results [data-slot="table-container"] {
  overflow-x: hidden;
}

.hw-selector-table {
  table-layout: fixed;
}

.hw-selector-table [data-slot="table-head"]:first-child,
.hw-selector-table [data-slot="table-cell"]:first-child {
  padding-right: 1rem;
}

.hw-selector-table [data-slot="table-head"]:nth-child(2),
.hw-selector-table [data-slot="table-cell"]:nth-child(2) {
  padding-left: 0.9rem;
}

.hw-selector-table [data-slot="table-body"] [data-slot="table-cell"] {
  padding-top: 0.55rem;
  padding-bottom: 0.55rem;
}

.hw-selector-model-cell {
  white-space: normal !important;
  width: 100%;
}

.hw-selector-model-wrap {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-width: 0;
}

.hw-selector-model-text {
  display: inline-block;
  min-width: 0;
}

.hw-selector-model-text-wrap {
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.hw-montajes-action-btn {
  gap: 0.75rem !important;
  padding-left: 1rem !important;
  padding-right: 1rem !important;
}

/* ── Empty / error states ─────────────────────────────────────────────── */

.hw-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 48px 16px;
  text-align: center;
}

.hw-error-state {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 48px 16px;
}

/* ── Card layout helpers ──────────────────────────────────────────────── */

.hw-card-body {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.hw-card-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.hw-card-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-top: 4px;
}

.hw-card-img {
  width: 100%;
  max-height: 420px;
  object-fit: cover;
  border-radius: 12px;
}

/* ── Profile page ─────────────────────────────────────────────────────── */

.hw-profile-card {
  padding: 28px;
  display: flex;
  gap: 24px;
  align-items: flex-start;
  flex-wrap: wrap;
}

.hw-profile-info {
  flex: 1;
  min-width: 200px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hw-profile-stats {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.hw-profile-actions {
  margin-top: 4px;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.hw-stat-chip {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px 20px;
  border-radius: 14px;
  min-width: 90px;
}

.hw-profile-avatar {
  width: 96px;
  height: 96px;
  font-size: 2rem;
}

.hw-profile-avatar-fallback {
  font-size: 1.6rem;
}

/* ── Action buttons (follow, chat, etc.) ──────────────────────────────── */

.hw-action-btn {
  font-size: 0.8rem;
  padding: 8px 20px;
  border-radius: 10px;
}

.hw-action-btn-outline {
  border-color: var(--hw-card-border);
}

/* ── Comment button ───────────────────────────────────────────────────── */

.hw-comment-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.78rem;
  padding: 6px 12px;
  border-radius: 10px;
  border: 1px solid var(--hw-card-border);
}

/* ── Name link button (in cards) ──────────────────────────────────────── */

.hw-name-link {
  background: none;
  border: none;
  padding: 0;
  font-size: 0.88rem;
  font-weight: 600;
  display: block;
}

/* ── Dialog title with icon ───────────────────────────────────────────── */

.hw-dialog-title-icon {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
}

/* ── Search result list container ─────────────────────────────────────── */

.hw-search-results {
  min-height: 120px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

/* ── Skeleton loading containers ──────────────────────────────────────── */

.hw-skeleton-list-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 4px;
}

/* ── Comment components ───────────────────────────────────────────────── */

.hw-comment-row {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.hw-comment-row-sm {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}

.hw-comment-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
}

.hw-comment-meta {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.hw-comment-name {
  background: none;
  border: none;
  padding: 0;
  font-size: 0.8rem;
  font-weight: 600;
}

.hw-comment-name-sm {
  background: none;
  border: none;
  padding: 0;
  font-size: 0.76rem;
  font-weight: 600;
}

.hw-comment-text {
  font-size: 0.82rem;
  line-height: 1.5;
  word-break: break-word;
}

.hw-comment-text-sm {
  font-size: 0.78rem;
  line-height: 1.5;
  word-break: break-word;
}

.hw-reply-thread {
  margin-left: 44px;
  margin-top: 8px;
  padding-left: 12px;
  border-left: 2px solid var(--hw-divider);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.hw-reply-input-wrap {
  margin-left: 44px;
  margin-top: 8px;
}

.hw-reply-btn {
  margin-top: 2px;
  padding: 2px 6px;
  height: auto;
  gap: 4px;
}

/* ── Comment input (textarea area) ────────────────────────────────────── */

.hw-comment-input-wrap {
  display: flex;
  gap: 8px;
  align-items: flex-end;
}

.hw-comment-input-wrap--border {
  border-top: 1px solid var(--hw-divider);
  padding-top: 14px;
  margin-top: 4px;
}

.hw-comment-textarea {
  flex: 1;
  resize: none;
  background: var(--hw-input);
  border: 1px solid var(--hw-input-border);
  border-radius: 10px;
  padding: 8px 12px;
  font-size: 0.8rem;
  line-height: 1.5;
  font-family: inherit;
  outline: none;
}

.hw-comment-send-btn {
  width: 32px;
  height: 32px;
  border-radius: 50%;
}

/* ── NewsCard/Grid ────────────────────────────────────────────────────── */

.hw-news-grid {
  column-gap: 8px;
  row-gap: 8px;
}

.hw-news-grid-item {
  padding: 10px;
}

.hw-news-card {
  margin: 10px;
}

.hw-news-card-img-wrap {
  height: 220px;
}

.hw-news-card-body {
  padding: 20px 24px 24px;
  box-sizing: border-box;
}

/* ── Dialog content padding override ──────────────────────────────────── */

.hw-dialog-padded {
  padding: 1.25rem 1.5rem;
}

.hw-start-chat-dialog {
  gap: 1.25rem !important;
}

.hw-start-chat-dialog-header {
  gap: 0.75rem !important;
}

.hw-start-chat-dialog-input {
  margin-top: 0.25rem;
}

.hw-start-chat-dialog-results {
  gap: 0.75rem;
}

/* ── Formulario de nueva publicación ──────────────────────────────────── */

.hw-pub-dialog-header {
  padding-bottom: 1.25rem;
}

.hw-pub-dialog-form {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  padding-top: 0.25rem;
  padding-bottom: 0.5rem;
}

.hw-pub-dialog-textarea {
  background: var(--hw-input);
  border-color: var(--hw-input-border);
  color: var(--hw-input-text);
  padding-left: 1rem !important;
  padding-right: 1rem !important;
}

.hw-pub-dialog-submit {
  height: auto;
  padding: 0.625rem 1.25rem;
}

/* ── Profile page ─────────────────────────────────────────────────────── */

.hw-profile-field {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.hw-profile-field-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.hw-profile-field-value {
  font-size: 0.88rem;
  font-weight: 500;
}

/* ── Stat chip with icon (row layout, PerfilPage variant) ────────────── */

.hw-stat-chip-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 20px;
  border-radius: 14px;
  min-width: 160px;
}

.hw-stat-chip-row-inner {
  display: flex;
  flex-direction: column;
}

.hw-stat-chip-row-value {
  font-size: 1.1rem;
  font-weight: 700;
}

.hw-stat-chip-row-label {
  font-size: 0.72rem;
}

/* ── Info row (account details) ───────────────────────────────────────── */

.hw-info-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 18px;
  border-radius: 12px;
}

/* ── Card section containers ──────────────────────────────────────────── */

.hw-card-section {
  padding: 28px;
}

.hw-card-section-title {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
}

.hw-card-section-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 10px;
}

/* ── Profile name heading ─────────────────────────────────────────────── */

.hw-profile-name {
  font-size: 1.35rem;
  font-weight: 700;
  margin: 0;
  line-height: 1.3;
}

.hw-profile-email {
  font-size: 0.82rem;
  margin: 4px 0 0;
}

/* ── Profile edit form ────────────────────────────────────────────────── */

.hw-profile-form {
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.hw-profile-form-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

/* ── Profile info column (PerfilPage variant, wider min-width) ────────── */

.hw-profile-info-wide {
  flex: 1;
  min-width: 240px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* ── Compare page ─────────────────────────────────────────────────────── */

.hw-compare-page {
  padding: 16px 20px 32px;
}

.hw-compare-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-right: 8px;
}

.hw-compare-section-separator {
  width: 100%;
  height: 18px;
  background: transparent;
}

.hw-compare-card-separator {
  border-top: 0;
  margin-top: 8px;
  padding-top: 10px;
}

.hw-compare-cats {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.hw-compare-cat-btn {
  font-size: 0.82rem;
  border-radius: 10px;
  padding: 8px 16px;
  gap: 6px;
}

.hw-compare-selectors {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.hw-compare-selector {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.hw-compare-selector-title {
  font-size: 0.85rem;
  font-weight: 600;
  margin: 0;
}

.hw-compare-selector-list {
  max-height: 260px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.hw-compare-selector-input {
  padding-left: 1.25rem !important;
  text-indent: 0.1rem;
}

.hw-compare-selector-item-main {
  display: flex;
  align-items: flex-start;
  column-gap: 0.9rem;
  width: 100%;
  min-width: 0;
}

.hw-compare-selector-item-text {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  row-gap: 0.12rem;
  padding-left: 0.12rem;
  overflow: hidden;
}

.hw-compare-selector-model {
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hw-compare-selector-fab {
  font-size: 0.68rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  opacity: 0.85;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hw-compare-skeleton-col {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.hw-compare-empty-text {
  font-size: 0.9rem;
}

.hw-compare-table-header {
  display: grid;
  grid-template-columns: 180px 1fr 1fr;
  padding: 18px 24px;
  gap: 20px;
}

.hw-compare-table-header-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  min-width: 0;
}

.hw-compare-table-header-thumb {
  display: flex;
  align-items: center;
  justify-content: center;
}

.hw-compare-table-header-label {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.hw-compare-table-header-model {
  font-size: 0.9rem;
  font-weight: 700;
  margin: 0;
  text-align: center;
  line-height: 1.35;
}

.hw-compare-table-header-fab {
  font-size: 0.7rem;
  margin: 0;
  text-align: center;
  opacity: 0.9;
}

.hw-compare-table-row {
  display: grid;
  grid-template-columns: 180px 1fr 1fr;
  padding: 14px 24px;
  gap: 20px;
  align-items: center;
}

.hw-compare-table-row-label {
  font-size: 0.78rem;
  font-weight: 500;
}

.hw-compare-table-cell {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.hw-compare-table-cell-value {
  font-size: 0.85rem;
}

.hw-compare-visual {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.hw-compare-visual-title {
  font-size: 0.85rem;
  font-weight: 600;
  margin: 0;
}

.hw-compare-visual-row {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.hw-compare-visual-labels {
  display: flex;
  justify-content: space-between;
  font-size: 0.72rem;
}

.hw-compare-bar-wrap {
  display: flex;
  gap: 8px;
  align-items: center;
}

.hw-compare-bar-track {
  direction: rtl;
}

/* ── Aprender page ────────────────────────────────────────────────────── */

.hw-aprender-page {
  padding: 12px 8px 16px;
}

.hw-aprender-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-right: 8px;
}

.hw-aprender-separator {
  width: 100%;
  height: 22px;
  background: transparent;
  margin: 0;
}

.hw-aprender-intro {
  padding: 24px 28px;
}

.hw-aprender-sections {
  display: flex;
  flex-direction: column;
  gap: 14px !important;
}

.hw-aprender-section-card + .hw-aprender-section-card {
  margin-top: 2px;
}

.hw-aprender-footer {
  padding: 32px 24px;
}

.hw-aprender-section-trigger {
  padding-left: 28px;
  padding-right: 24px;
  gap: 16px;
}

.hw-aprender-section-icon-wrap {
  margin-left: 2px;
}

.hw-aprender-section-title {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 600;
}

.hw-aprender-section-content {
  padding: 14px 24px 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ── Ayuda page ───────────────────────────────────────────────────────── */

.hw-ayuda-page {
  padding: 12px 8px 16px;
}

.hw-ayuda-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-right: 8px;
}

.hw-ayuda-separator {
  width: 100%;
  height: 22px;
  background: transparent;
}

.hw-ayuda-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hw-ayuda-section-title {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
  padding-left: 4px;
}

.hw-ayuda-section-items {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.hw-ayuda-category-separator {
  width: 100%;
  height: 18px;
  background: transparent;
}

.hw-ayuda-item-trigger {
  gap: 12px;
  padding: 16px 20px;
}

.hw-ayuda-item-answer {
  font-size: 0.84rem;
  line-height: 1.65;
  margin: 0;
  padding: 0 20px 16px;
}

.hw-ayuda-footer {
  padding: 32px 24px;
}

.hw-ayuda-footer-title {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
}

.hw-ayuda-footer-text {
  font-size: 0.84rem;
  margin: 8px 0 0;
}
